  "home.today_text": "New memorisation, then two revision pages. Star for a steady voice.",
  "home.parents_card": "For parents",
  "home.parents_title": "See homework, attendance, and recordings",
  "home.parents_text": "One login. Every child. No chasing teachers on WhatsApp.",
  "home.classroom": "In the classroom",
  "home.classroom_text":
    "Teacher and students share live video, audio, one screen at a time, text chat, lesson files, PowerPoint slides with live annotation, PDF and digital book pages with flipbook turning, page navigation, zoom, fullscreen, bookmarks, thumbnails, and teacher/student page synchronisation, collaborative Arabic and RTL marking, Tajweed-rule colours, a lesson timer, secure lesson recording with access controls and retention, and an interactive whiteboard on one page — {name} stays visible for the whole lesson.",
  "home.subjects_eyebrow": "Subjects",
  "home.subjects_title": "A path for every learner",
  "home.subjects_description":
    "Child-friendly lessons that stay serious about the Qur'an, language, and adab.",
  "home.how_eyebrow": "How it works",
  "home.how_title": "Three gentle steps",
  "home.how_description":
    "Large buttons, clear words, and a layout that works on a phone in a parent's hand.",
  "home.step1_title": "Choose a teacher",
  "home.step1_text": "Filter by subject, language, gender, and the age they teach.",
  "home.step2_title": "Book a calm first lesson",
