  "parents.eyebrow": "Families",
  "parents.title": "A parent account that actually parents",
  "parents.description":
    "Children learn. You book, pay, and watch progress. Teachers never need your personal phone number.",
  "parents.point1_title": "One parent, many children",
  "parents.point1_text":
    "Add each child, book their lessons, and keep their progress separate.",
  "parents.point2_title": "You stay in control",
  "parents.point2_text":
    "Payments, schedules, homework, and teacher messages come to you.",
