  "about.eyebrow": "About",
  "about.title": "A teaching marketplace with an Islamic classroom at its heart",
  "about.description":
    "Not a generic LMS. Not a booking page. A complete home for Qur'an, Tajweed, Hifdh, Arabic, and Islamic Studies.",
  "about.p1":
    "Families should find a teacher, join a branded {name} lesson, and see progress without leaving the platform. Teachers should apply, teach, and be paid without collecting student phone numbers.",
  "about.p2":
    "The company mark, colours, and name stay on every public screen, every account page, and the classroom overlay Super Admin configures.",
