  "ai.kind.help.transcription":
    "English (en-GB) and Arabic (ar-SA, where the browser supports it) speech-to-text from the live lesson or recording, plus searchable transcripts. Each microphone and lesson chat keeps speakers separate where possible.",
  "ai.kind.help.summary":
    "Write a short lesson summary, key learning points, vocabulary, improvement areas, and next-lesson recommendations from the transcript. They stay extractive, so they do not invent speech, meanings, or a plan. A teacher must approve them before learners see them.",
  "ai.kind.help.notes":
    "A learner can jot private notes during a lesson, or write them from an approved transcript. Typed notes stay with that learner. Classmates, parents, and teachers cannot read them.",
  "ai.kind.help.homework":
    "Teachers generate extractive homework drafts from a lesson transcript or typed notes. The draft does not invent tasks. A teacher must approve it before learners see it, and AI cannot assign it on its own.",
  "ai.kind.help.quiz":
    "Teachers generate extractive quiz drafts from a lesson transcript, a library book, a question-bank topic, an uploaded document, or previous lesson content. The draft does not invent questions or answers. A teacher must approve it before learners see it, and AI cannot publish the quiz.",
  "ai.kind.help.recommendation":
    "Teachers generate extractive learning recommendations from a lesson transcript or previous lesson content. The draft does not invent a plan. A teacher must approve it before learners see it, and AI cannot assign the recommended work.",
