  "classroom.role_parent": "Parent observer",
  "classroom.role_staff": "Staff",
  "classroom.integrated_title": "A branded classroom that stays on the platform",
  "classroom.integrated_help":
    "One-to-one or a group class: everyone joins the same room. Teachers and students control camera, microphone, and screen sharing, share lesson files, present a PowerPoint, PDF, or EPUB book, turn pages as a flipbook, jump with page numbers, thumbnails, and bookmarks, zoom or open fullscreen, keep teacher and student pages in sync, and annotate the pages together, mark Tajweed rules in English or Arabic RTL, use text chat, follow a lesson timer, and record the lesson into encrypted platform storage that only the teacher, student, parent, and safeguarding staff can watch, for a set number of days. Super Admin sets the overlay.",
  "library.eyebrow": "LMS",
  "library.title": "Teaching library",
  "library.help":
    "Qur'an books, Arabic books, Islamic Studies books, teacher guides, worksheets, presentations, videos, audio, games, and assessments. Teacher guides stay with teachers and staff. Entitled items open only with the right role, course, subscription, licence, or purchase grant.",
  "library.student_help":
    "Read Qur'an, Arabic, and Islamic Studies books as flipbooks, then open worksheets, presentations, videos, audio, games, and assessments your course, subscription, licence, or purchase unlocks. Play video, audio, PDF, and flipbook lessons in prerecorded courses in order and keep your progress. Some items are view-only and cannot be downloaded.",
  "library.family_help":
    "Read the same Qur'an, Arabic, and Islamic Studies books your child can open, and see their prerecorded course progress. Teacher guides stay with teachers. Restricted items stay in the library and cannot be downloaded.",
  "library.teacher_help":
    "Upload PDF or EPUB Qur'an, Arabic, and Islamic Studies books, then add teacher guides, worksheets, presentations, videos, audio, games, and assessments. Sequence video, audio, PDF, and flipbook files as prerecorded course lessons. Teacher guides stay with teachers and staff. Staff can lock learner items to a course, subscription, licence, or purchase grant, and restrict downloads so families read in the library only.",
  "library.book_help":
    "Turn pages as a flipbook. Use page numbers, zoom, fullscreen, bookmarks, and thumbnails. Arabic and Qur'an pages open right-to-left when the file is RTL.",
  "library.book_file_help": "Upload a PDF or EPUB. The platform turns it into readable pages.",
