    "classroom.role_staff": "موظف",
    "classroom.integrated_title": "فصل يحمل العلامة ويبقى على المنصة",
    "classroom.integrated_help":
      "درس فردي أو صف جماعي: ينضم الجميع إلى الغرفة نفسها. يتحكم المعلم والطالب بالكاميرا والميكروفون ومشاركة الشاشة، ويشاركون ملفات الدرس، ويعرضون باوربوينت أو PDF أو كتاب EPUB ويقلبون الصفحات ككتاب وينتقلون بأرقام الصفحات والمصغرات والإشارات المرجعية ويكبّرون أو يفتحون ملء الشاشة ويُبقون صفحات المعلم والطالب متزامنة ويعلّقون عليها معاً، ويعلّمون أحكام التجويد بالعربية من اليمين إلى اليسار أو بالإنجليزية، ويستخدمون الدردشة النصية، ويتبعون مؤقت الدرس، ويسجّلون الدرس في تخزين مشفّر لا يشاهده إلا المعلم والطالب وولي الأمر وموظفو الحماية ولعدد محدد من الأيام. يضبط المشرف العام الطبقة الظاهرة.",
    "library.eyebrow": "نظام التعلّم",
    "library.title": "مكتبة التعليم",
    "library.help":
      "كتب القرآن والعربية والدراسات الإسلامية وأدلة المعلمين وأوراق العمل والعروض والفيديوهات والصوتيات والألعاب والتقييمات. تبقى أدلة المعلمين للمعلمين والموظفين. تُفتح المواد المشروطة فقط بالدور أو الدورة أو الاشتراك أو الرخصة أو منحة الشراء المناسبة.",
    "library.student_help":
      "اقرأ كتب القرآن والعربية والدراسات الإسلامية ككتب تقلب، ثم افتح أوراق العمل والعروض والفيديوهات والصوتيات والألعاب والتقييمات التي تفتحها دورتك أو اشتراكك أو رخصتك أو عملية الشراء. شغّل دروس الفيديو والصوت وPDF والكتاب القلّاب في الدورات المسجّلة بالترتيب وتابع تقدمك. بعض المواد للعرض فقط ولا يمكن تنزيلها.",
    "library.family_help":
      "اقرأ كتب القرآن والعربية والدراسات الإسلامية نفسها التي يفتحها طفلك، وتابع تقدمهم في الدورات المسجّلة. تبقى أدلة المعلمين للمعلمين. تبقى المواد المقيّدة في المكتبة ولا تُنزَّل.",
    "library.teacher_help":
      "ارفع كتب قرآن وعربية ودراسات إسلامية بصيغة PDF أو EPUB، ثم أضف أدلة المعلمين وأوراق العمل والعروض والفيديوهات والصوتيات والألعاب والتقييمات. رتّب ملفات الفيديو والصوت وPDF والكتاب القلّاب كدروس في الدورات المسجّلة. تبقى أدلة المعلمين للمعلمين والموظفين. يمكن للموظفين قفل مواد الطلاب بدورة أو اشتراك أو رخصة أو منحة شراء، وتقييد التنزيل حتى تبقى القراءة داخل المكتبة.",
    "library.book_help":
      "قلّب الصفحات ككتاب. استخدم أرقام الصفحات والتكبير وملء الشاشة والإشارات المرجعية والمصغرات. تُفتح صفحات العربية والقرآن من اليمين إلى اليسار عندما يكون الملف كذلك.",
    "library.book_file_help": "ارفع ملف PDF أو EPUB. تحوّله المنصة إلى صفحات قابلة للقراءة.",
    "library.book_empty": "لا توجد صفحات قابلة للقراءة في هذا الكتاب بعد.",
    "library.slides_help":
      "انتقل بين الشرائح بأرقام الصفحات والتكبير وملء الشاشة والإشارات المرجعية والمصغرات.",
    "library.video_help":
      "شاهد فيديو الدرس في المكتبة. يظهر التنزيل فقط عندما لا يكون الملف مقيّداً.",
    "library.audio_help":
      "استمع إلى صوت الدرس في المكتبة. يظهر التنزيل فقط عندما لا يكون الملف مقيّداً.",
